package com.ryanjei.orushio.pve.map;import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
class TemporaryWorldManagerTest{@TempDir Path temp;@Test void 原本を変更せず一時コピーだけ削除する()throws Exception{MapProfile p=profile();Path original=temp.resolve("maps/a/template/level.dat");String before=Files.readString(original);TemporaryWorldManager m=new TemporaryWorldManager(temp.resolve("maps"),temp.resolve("worlds"));var w=m.create(p,"setup");Files.writeString(w.directory().resolve("changed.txt"),"x");m.delete(w);assertFalse(Files.exists(w.directory()));assertEquals(before,Files.readString(original));}@Test void 無関係ディレクトリを削除せず所有worldだけ回収する()throws Exception{MapProfile p=profile();TemporaryWorldManager m=new TemporaryWorldManager(temp.resolve("maps"),temp.resolve("worlds"));var owned=m.create(p,"run");Path unrelated=temp.resolve("worlds/orushio_run_unrelated");Files.createDirectories(unrelated);Files.writeString(unrelated.resolve("level.dat"),"x");assertEquals(1,m.recoverOwnedWorlds().size());assertFalse(Files.exists(owned.directory()));assertTrue(Files.exists(unrelated));}@Test void 所有情報不一致では削除しない()throws Exception{MapProfile p=profile();TemporaryWorldManager m=new TemporaryWorldManager(temp.resolve("maps"),temp.resolve("worlds"));var w=m.create(p,"run");var fake=new TemporaryWorldManager.OwnedWorld(w.worldName(),w.mapId(),w.purpose(),"wrong",w.directory());assertThrows(MapIoException.class,()->m.delete(fake));assertTrue(Files.exists(w.directory()));}private MapProfile profile()throws Exception{MapProfile p=MapProfileTest.empty("a");Path dir=temp.resolve("maps/a/template");Files.createDirectories(dir);Files.writeString(dir.resolve("level.dat"),"original");return p;}}
